#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"

/* Tunable blocking factors for the main kernel.
 * These can be overridden at compile time, e.g.:
 *   -DGEMVER_BLOCK_SIZE_I=128 -DGEMVER_BLOCK_SIZE_J=32
 */
#ifndef GEMVER_BLOCK_SIZE_I
# define GEMVER_BLOCK_SIZE_I 64
#endif

#ifndef GEMVER_BLOCK_SIZE_J
# define GEMVER_BLOCK_SIZE_J 64
#endif


/* Array initialization. (kept identical for comparability) */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j, ii, jj;

  /* Local restrict-qualified aliases for better alias analysis and
     vectorization. PolyBench guarantees these arrays do not overlap. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict u1_ = u1;
  DATA_TYPE *restrict v1_ = v1;
  DATA_TYPE *restrict u2_ = u2;
  DATA_TYPE *restrict v2_ = v2;
  DATA_TYPE *restrict w_  = w;
  DATA_TYPE *restrict x_  = x;
  DATA_TYPE *restrict y_  = y;
  DATA_TYPE *restrict z_  = z;

  const int N    = _PB_N;
  const int BS_I = GEMVER_BLOCK_SIZE_I;
  const int BS_J = GEMVER_BLOCK_SIZE_J;

#pragma scop

  /* 1. Rank-1 updates on A:
         A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
     - Row-major traversal (A_[i][j]) for good spatial locality.
     - u1[i] and u2[i] are hoisted into registers. */
  for (i = 0; i < N; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];
    const DATA_TYPE u1_i = u1_[i];
    const DATA_TYPE u2_i = u2_[i];

    for (j = 0; j < N; j++)
      Ai[j] += u1_i * v1_[j] + u2_i * v2_[j];
  }

  /* 2. x := x + beta * A^T * y
     Original code (column-wise traversal of A, poor locality):
       for (i)
         for (j)
           x[i] += beta * A[j][i] * y[j];

     We instead traverse A by rows while preserving, for each x[i],
     the order of updates over j (hence preserving FP semantics):

       for (j)
         for (i)
           x[i] += beta * A[j][i] * y[j];

     Additionally, we block both the j and i dimensions with tunable
     sizes BS_J and BS_I to improve cache behavior for large N. */
  for (jj = 0; jj < N; jj += BS_J)
  {
    const int j_end = (jj + BS_J < N) ? (jj + BS_J) : N;

    for (j = jj; j < j_end; j++)
    {
      const DATA_TYPE beta_yj = beta * y_[j];
      const DATA_TYPE *restrict Aj = A_[j]; /* Row j of A */

      for (ii = 0; ii < N; ii += BS_I)
      {
        const int i_end = (ii + BS_I < N) ? (ii + BS_I) : N;

        for (i = ii; i < i_end; i++)
          x_[i] += beta_yj * Aj[i];
      }
    }
  }

  /* 3. x := x + z (element-wise, trivially vectorizable). */
  for (i = 0; i < N; i++)
    x_[i] += z_[i];

  /* 4. w := w + alpha * A * x
     Original:
       for (i)
         for (j)
           w[i] += alpha * A[i][j] * x[j];

     We keep the row-major traversal of A, but:
       - Accumulate into a scalar 'sum' per row to reduce memory traffic
         on w[i] (only one store per row).
       - Block over i with BS_I to improve cache reuse of A and w
         when N is large. */
  for (ii = 0; ii < N; ii += BS_I)
  {
    const int i_end = (ii + BS_I < N) ? (ii + BS_I) : N;

    for (i = ii; i < i_end; i++)
    {
      const DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE sum = w_[i];

      for (j = 0; j < N; j++)
        sum += alpha * Ai[j] * x_[j];

      w_[i] = sum;
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemver (n, alpha, beta,
		 POLYBENCH_ARRAY(A),
		 POLYBENCH_ARRAY(u1),
		 POLYBENCH_ARRAY(v1),
		 POLYBENCH_ARRAY(u2),
		 POLYBENCH_ARRAY(v2),
		 POLYBENCH_ARRAY(w),
		 POLYBENCH_ARRAY(x),
		 POLYBENCH_ARRAY(y),
		 POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
